#!/usr/bin/env python3
"""Editorial ninja equipment: documented reskin choices and original bounded drafts."""
import json,re
from pathlib import Path
import yaml
ROOT=Path(__file__).resolve().parents[1];folder=ROOT/'catalog/settings/ninja';folder.mkdir(parents=True,exist_ok=True)
def save(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');p.with_suffix('.yaml').write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False))
refs=[
 {'id':'ninja-2e','url':'https://d1vzi28wh99zvq.cloudfront.net/pdf_previews/16904-sample.pdf','label':"The Complete Ninja’s Handbook (PHBR15 / TSR 2155)",'edition':'AD&D 2e','author':'Aaron Allston','source_kind':'publisher-preview','note':'Preview establishes identity and chapter locators only. Item-name leads separately indexed; full equipment and magic-item chapters not audited.'},
 {'id':'ninja-equipment-index','url':'https://dokumen.pub/complete-ninjas-handbook-paperbacknbsped-0786901594-9780786901593.html','label':'Ninja handbook equipment table search index','source_kind':'unverified-third-party-OCR-index','note':'Selected names attested in indexed table excerpt; no source prose, costs, damage tables or complete chapter reproduced. Original-page verification pending.'},
 {'id':'oa-3e','url':'https://dnd-wiki.org/wiki/Publication%3AOriental_Adventures_%283e%29','label':'Oriental Adventures (WTC12015, 2001)','edition':'D&D 3.0','author':'James Wyatt','source_kind':'bibliography-and-table-of-contents','note':'Equipment pp. 70–75 and magic-item chapter located; not an item-by-item audit. 3.0 is distinct from 1985 1e OA and Dragon 318 3.5 update.'},
 {'id':'oa-fan-gear','url':'https://www.electric-rain.net/2016/07/22/oriental-advenutres-gear/','label':'electric RAIN equipment conversion','source_kind':'fan-conversion-index','note':'Secondary names and reskin leads. New project mappings below do not reproduce this author’s mechanics or certify source-book attribution.'},
 {'id':'oa-fan-magic','url':'https://www.electric-rain.net/2016/08/17/oriental-adventures-magic-items/','label':'electric RAIN mixed 1e / 3e OA item index','source_kind':'mixed-edition-fan-conversion-index','note':'Explicitly mixes 1e and 3e. Item-specific legacy edition remains unverified; do not label every item as 3e canon. Original rules below are independent lesser adaptations.'},
 {'id':'sekiro','url':'https://sekiroshadowsdietwice.wiki.fextralife.com/Prosthetic+Tools','source_kind':'fan-tool-index','label':'Sekiro prosthetic tools'},
 {'id':'tenchu','url':'https://tenchu.fandom.com/wiki/List_of_Items','source_kind':'fan-item-index-search-excerpts','label':'Tenchu tool lists','note':'Selected names only; editions differ.'},
 {'id':'gaiden','url':'https://ninjagaiden.fandom.com/wiki/Dabilahro','source_kind':'fan-weapon-index-search-excerpt','label':'Ninja Gaiden weapons','note':'Selected named weapons from linked series list; no blanket all-release coverage.'},
 {'id':'nioh','url':'https://liukang1080.github.io/gamewiki/nioh2/tools/smithing_texts/weapon_texts.html','source_kind':'fan-smithing-index','label':'Nioh 2 weapon names'},
 {'id':'d2-assassin','url':'https://classic.battle.net/diablo2exp/items/normal/uassassin.shtml','source_kind':'official-game-guide','label':'Diablo II unique Assassin weapons'}]
entities=[]
def entity(kind,key,label,aliases=(),parents=(),note=''):
 entities.append({'id':kind+':'+key,'kind':kind,'label':label,'aliases':list(aliases),'parent_ids':list(parents),'note':note})
entity('topic','ninja-equipment','Ninja equipment',('ninja','shinobi','ninja gear'),note='Editorial play-style theme, not ancestry or a new 2024 class. Not all adjacent samurai gear is ninja-specific.')
for k,l,a in [('complete-ninja-handbook',"The Complete Ninja’s Handbook",('Ninjas Handbook','Ninja Handbook','PHBR15')),('oriental-adventures-3e','Oriental Adventures (3e)',('OA 3e','Oriental Adventures 3rd edition')),('oriental-adventures-mixed','Oriental Adventures mixed-edition research',())]:entity('publication',k,l,a)
for k,l in [('sekiro','Sekiro: Shadows Die Twice'),('tenchu','Tenchu series'),('ninja-gaiden','Ninja Gaiden series'),('nioh-2','Nioh 2')]:entity('game',k,l)
entity('setting','rokugan','Rokugan',note='Featured setting in 2001 OA, distinct from Kara-Tur; not automatically assigned to every weapon in that book.')
items=[]
slug=lambda x:re.sub(r'[^a-z0-9]+','-',x.casefold()).strip('-')
# One named implement, one draft. Shared statistics use one SRD base definition.
weapons=[('Bo','quarterstaff','staff'),('Hanbo','club','staff'),('Jo','club','staff'),('Kama','sickle','dagger'),('Jitte','club','dagger'),('Kusari-gama','flail','flail'),('Kawanaga','whip','rope'),('Kyogetsu-shogi','whip','rope'),('Manriki-gusari','flail','flail'),('Kau sin ke','flail','flail'),('Gunsen','club','gear'),('Nunchaku','club','flail'),('Sai','dagger','dagger'),('Shuriken','dart','ammunition'),('Nekode','dagger','gloves'),('Kumade','glaive','spear'),('Lajatang','glaive','spear'),('Nagimaki','halberd','spear'),('Naginata','glaive','spear'),('Sode garami','pike','spear'),('Chijiriki','spear','spear'),('Sang kauw','spear','spear'),('Shakujo yari','spear','spear'),('Daikyu','longbow','bow'),('Hankyu','shortbow','bow'),('Fukimi-bari','dart','ammunition'),('Siangkam','dagger','dagger'),('Kiseru','club','gear')]
for name,base,icon in weapons:
 extra=''
 if name in ['Kusari-gama','Kawanaga','Kyogetsu-shogi','Manriki-gusari','Kau sin ke','Chijiriki']:extra=' This approximation grants no free Grapple, disarm, pull, extra attack, or second damage roll from its chain or cord.'
 if name=='Nekode':extra=' These combat statistics grant no Climb Speed or automatic success on climbing checks.'
 if name=='Gunsen':extra=' This weapon mapping grants no shield AC bonus.'
 if name=='Fukimi-bari':extra=' This adaptation is thrown by hand; it does not grant a hands-free attack from the mouth.'
 details=f'Use the 2024 {base.replace("-"," ").title()} equipment rules, including its damage, properties, mastery access and training category. This is an approximate project mapping, not a historical performance claim.'+extra
 items.append(dict(id='ninja:'+slug(name),name=name,base_item_id='open5e-srd-2024:srd-2024_'+base,type='weapon',icon=icon,mode='2024-equipment-reskin',magic=False,evidence_ref='ninja-equipment-index',entity_id='publication:complete-ninja-handbook',locator='Indexed equipment table; original page not verified',estimated_value_gp=5,tldr='A regional implement using a standard 2024 weapon profile.',details=details,changes='Legacy weapon-speed, size-vs-target and entangling rules replaced by the named SRD profile. Training is based on this draft’s base weapon, not a ninja class allowlist.',flavor='Worn bindings reveal where its owner prefers to place a hand.',creative='Use the implement’s appearance as a disguise or trade clue. Extra mechanical advantages require the DM’s ruling.'))
for name,base,typ,icon,value in [('Katana','longsword','weapon','sword',15),('Wakizashi','shortsword','weapon','sword',10),('Ninja-to','shortsword','weapon','sword',10),('No-dachi','greatsword','weapon','sword',50),('Tetsubo','greatclub','weapon','hammer',2),('Tonfa','club','weapon','hammer',1),('Tessen','shield','shield','shield',10),('Ashigaru Armor','padded-armor','armor','light-armor',5),('Leather Scale','leather-armor','armor','light-armor',10),('Kusari Gusoku','chain-shirt','armor','medium-armor',50)]:
 items.append(dict(id='ninja:'+slug(name),name=name,base_item_id='open5e-srd-2024:srd-2024_'+base,type=typ,icon=icon,mode='2024-equipment-reskin',magic=False,evidence_ref='oa-fan-gear',entity_id='publication:oriental-adventures-3e',locator='Secondary equipment-name/mapping lead; original 2001 page verification pending',estimated_value_gp=value,tldr='Uses a standard 2024 equipment profile.',details=f'Use the 2024 {base.replace("-"," ").title()} rules. No legacy exotic-weapon proficiency, layered armor AC, independent offhand fan attack, or bonus attack is added. The item retains this base profile’s normal limitations.',changes='Project approximation; source-name attribution and edition need review. Uses base equipment training and mastery prerequisites; aesthetic changes do not create new proficiency grants.',flavor='Careful workmanship favors a steady hand over an extravagant finish.',creative='Let local artisans recognize its style. Recognition supplies a roleplaying opening, not an automatic social bonus.'))
def custom(key,name,ref,entity,typ,icon,value,tldr,details,changes,creative,flavor,magic=False,rarity=None,attune=False,base=None,tags=()):
 items.append(dict(id='ninja:'+key,name=name,evidence_ref=ref,entity_id=entity,type=typ,icon=icon,estimated_value_gp=value,tldr=tldr,details=details,changes=changes,creative=creative,flavor=flavor,magic=magic,rarity=rarity,attunement=attune,base_item_id=base,mode='original-homebrew-adaptation',tags=list(tags)))
# Equipment has costs and limits; no real-world chemical preparation or recipes.
custom('metsubishi','Metsubishi Dust Packet','ninja-equipment-index','publication:complete-ninja-handbook','consumable','dye',20,'A single-use close-range distraction.', 'As a Utilize action, expend a packet against one creature within 5 feet. It makes a DC 12 Dexterity saving throw. On a failure it has Disadvantage on its next attack roll before the end of its next turn. A creature that does not rely on sight automatically succeeds. The packet creates no lingering cloud and does not impose the Blinded condition.', 'New bounded game effect replaces legacy blinding powders. No crafting formula.', 'Use an opening to withdraw; it does not prevent opportunity attacks or guarantee escape.', 'A paper seal keeps the fine theatrical dust dry.')
custom('smoke-egg','Smoke Egg','tenchu','game:tenchu','consumable','potion',50,'A fragile charge briefly obscures a small area.', 'As a Utilize action, throw and expend the egg at a point within 20 feet. A 5-foot-radius cloud centered there is Heavily Obscured until the start of your next turn. A strong wind disperses it immediately. The cloud does not move with you and blocks allies’ sight normally.', 'Original game-only smoke effect; not a modern weapon recipe or copied Tenchu statistics.', 'Break line of sight before hiding. You still need to satisfy the normal Hide requirements.', 'A thin ceramic shell rattles softly when shaken.')
custom('colored-rice','Colored Rice Trail Kit','tenchu','game:tenchu','adventuring-gear','food',2,'Leave coded trail marks for a small team.', 'The kit contains 20 uses of colored, nonfood trail grains. A Utilize action marks a visible surface within reach and expends one use. Agree on meanings beforehand. Marks are mundane: rain, sweeping, hungry animals or another traveler can remove them. Spotting hidden marks and interpreting codes use normal DM-set checks.', 'Original tracking abstraction; no automatic map reveal or tracking immunity.', 'Mark which doors were checked. An enemy who learns your code can exploit it.', 'Five muted colors fit in separate cloth folds.')
custom('decoy-whistle','Decoy Whistle','tenchu','game:tenchu','adventuring-gear','instrument',5,'Make a controlled sound to test a guard’s attention.', 'As a Utilize action, produce a birdlike note audible up to 120 feet under ordinary quiet conditions. The sound comes from your location. It does not compel movement, impose a condition, or automatically fool a listener. The DM resolves distraction and identification normally.', 'Sound tool only; game AI luring is not mind control.', 'Signal a lookout with a prearranged rhythm. Someone else may hear and learn it.', 'Its reed is wrapped to soften the sharpest notes.')
custom('climbing-claw-kit','Climbing Claw Kit','ninja-equipment-index','publication:complete-ninja-handbook','adventuring-gear','gloves',25,'Claws and anchor straps help a prepared climber.', 'Uses the 2024 Climber’s Kit rules. The claws require hands and appropriate terrain and do not grant a Climb Speed, ceiling walking, or an automatic successful check. This is distinct from the Nekode combat reskin.', 'Reskins climbing safety equipment; avoids doubling the combat and utility benefit in one cheap weapon.', 'Plan anchor points before the climb. Stone texture and anchor access still matter.', 'Replaceable iron tips bear years of scratches.',base='open5e-srd-2024:srd-2024_climbers-kit')
custom('humming-arrow','Humming Signal Arrow','ninja-equipment-index','publication:complete-ninja-handbook','ammunition','ammunition',2,'An arrow makes an audible signal in flight.', 'This is one arrow compatible with a bow. When fired, it whistles audibly within 120 feet of its flight path in ordinary conditions. It uses normal attack and ammunition rules, adds no damage, and reveals the shot’s direction to attentive listeners. Recovery follows the normal ammunition rules.', 'No automatic Fear or morale check is imported.', 'Time a coordinated move by sound; the enemy hears the same cue.', 'The hollow head sings a single clear note.')
custom('water-reed','Scout’s Breathing Reed','tenchu','game:tenchu','adventuring-gear','gear',1,'A short reed helps a motionless scout breathe at the surface.', 'While your mouth is just below calm water and the open reed remains above it, you can breathe through it. It grants no Water Breathing, Swim Speed, pressure protection or resistance to drowning if blocked. Talking, moving quickly or losing the reed interrupts its use. The DM judges concealment normally.', 'Original mundane abstraction; not deep-water equipment.', 'Watch a shallow bank from cover. Ripples and the exposed reed may give you away.', 'A waxed cord keeps the reed close at hand.')
# Original lesser magic adaptations, deliberately bounded for 2024 review.
custom('mist-step-mantle','Mist-Raven Mantle','sekiro','game:sekiro','cloak','cloak',4000,'A short reaction teleport helps evade a strike.', 'Requires attunement. Once per Long Rest, when a creature you can see hits you with an attack, you can use your Reaction to teleport up to 10 feet to an unoccupied space you can see. The triggering attack still deals its damage and other effects. You cannot teleport through a solid barrier, and this property does not negate conditions already imposed.', 'Inspired by Mist Raven; no automatic damage negation, invulnerability, spirit-emblem system or retaliation.', 'Reach cover after a hit. Reserve your Reaction and keep an escape space visible.', 'Black feathers dissolve into pale vapor at the hem.',True,'rare',True)
custom('folding-umbrella','Guardian’s Folding Umbrella','sekiro','game:sekiro','shield','shield',410,'A shield can cushion one ranged hit each day.', 'Requires attunement. Uses the 2024 Shield rules. Once per Long Rest, when a ranged weapon attack hits you while you wield it, use your Reaction to reduce the attack’s damage by 1d10 + your Proficiency Bonus, to a minimum of 0. It does not reflect projectiles, protect allies, or grant immunity to Fire or psychic effects.', 'Original Loaded Umbrella adaptation; no universal block or posture mechanic.', 'Cross an exposed gap with one layer of protection; several attackers can exhaust it.', 'Lacquered ribs snap open like a dark flower.',True,'uncommon',True,'open5e-srd-2024:srd-2024_shield')
custom('returning-wind-star','Returning Wind Star','gaiden','game:ninja-gaiden','weapon','ammunition',400,'A magic dart returns after a ranged attack.', 'Requires attunement. Uses the 2024 Dart rules. Immediately after you make a ranged attack with it, it returns to your empty hand if you are within 60 feet of it. Otherwise it falls normally. It adds no attack or damage bonus, grants no extra attacks, and cannot retrieve or carry other objects.', 'Original lesser Windmill Shuriken adaptation; no sweeping multi-hit or charge attack.', 'Avoid leaving a distinctive projectile at a scene. A full hand can interrupt the return.', 'Curved blades circle a ring of worn blue steel.',True,'uncommon',True,'open5e-srd-2024:srd-2024_dart')
custom('dragon-oath-blade','Dragon-Oath Blade','gaiden','game:ninja-gaiden','weapon','sword',4015,'A +1 blade has a limited burst against a formidable foe.', 'Requires attunement. Uses the 2024 Longsword rules with +1 to attack and damage rolls. Once per Long Rest, when you hit with it, you can deal an extra 2d6 Force damage to that target. The choice requires no additional action and does not grant another attack.', 'Original Dragon Sword-inspired lesser weapon; not a full port of an artifact or its upgrade tree.', 'Save the burst for a dangerous target; the bonus damage does not spread to nearby enemies.', 'A tiny dragon circles the guard, its jaws closed.',True,'rare',True,'open5e-srd-2024:srd-2024_longsword')
custom('hungry-night-blade','Hungry Night Blade','gaiden','game:ninja-gaiden','weapon','sword',4015,'A cursed +1 sword trades restraint for a small reserve.', 'Requires attunement. Uses the 2024 Longsword rules with +1 to attack and damage rolls. Once per Long Rest, when you hit a hostile creature with it, you can gain 1d6 Temporary Hit Points. Curse: while attuned, you have Disadvantage on Wisdom (Insight) checks to judge offers of mercy. Remove Curse ends attunement normally. The sword cannot steal permanent Hit Points or healing.', 'Kitetsu-inspired original curse; no unavoidable per-second health drain or scaling life steal.', 'The reserve may help in a duel, but the curse can distort a negotiation. Tell the DM when it applies.', 'The sheath feels colder after every drawn blade.',True,'rare',True,'open5e-srd-2024:srd-2024_longsword',('curse:present',))
custom('shadow-reed-mask','Shadow-Reed Mask','tenchu','game:tenchu','wondrous-item','helmet',400,'A brief disguise can help a planned infiltration.', 'Requires attunement. Once per Long Rest, as a Magic action, cast Disguise Self without a spell slot or components. Use the spell’s normal duration, limits and investigation rules, with a spell save DC of 13. Your voice, knowledge, documents and behavior are unchanged.', 'Original Chameleon-tool adaptation; no guaranteed impersonation or faction access.', 'Prepare a plausible role before using the mask. A matching face cannot answer every challenge.', 'A plain reed mask reflects the face you have rehearsed.',True,'uncommon',True)
custom('jade-talon-ward','Jade-Talon Ward','d2-assassin','game:diablo-2','weapon','dagger',4002,'A claw-shaped dagger offers brief protection from poison.', 'Requires attunement. Uses the 2024 Dagger rules, with no attack or damage bonus. Once per Long Rest, as a Bonus Action while holding it, gain Resistance to Poison damage for 1 minute. This property does not end the Poisoned condition or protect against other damage types.', 'Original lesser Jade Talon adaptation; no mana, class skill levels, percentage life leech or all-resistance stacking.', 'Prepare before entering a venomous lair; resistance is not immunity to its hazards.', 'Green stone is set into the inside of each talon.',True,'uncommon',True,'open5e-srd-2024:srd-2024_dagger')
custom('cutthroats-cestus','Cutthroat’s Cestus','d2-assassin','game:diablo-2','weapon','dagger',4002,'A +1 dagger rewards a carefully timed opening.', 'Requires attunement. Uses the 2024 Dagger rules with +1 to attack and damage rolls. Once per Long Rest, when you hit a creature that has not yet taken a turn in this combat, deal an extra 1d6 damage of the weapon’s type. It does not alter Initiative or grant Surprise.', 'Original Bartuc-inspired lesser weapon; no automatic Assassin proficiency, multi-claw attack or game-level requirements.', 'Plan the opening strike, while remembering that Initiative may leave no valid target.', 'A padded grip muffles the click of the metal claws.',True,'rare',True,'open5e-srd-2024:srd-2024_dagger')
custom('storm-chain-sickle','Storm-Chain Sickle','nioh','game:nioh-2','weapon','flail',4010,'A +1 chain weapon can release one crack of thunder.', 'Requires attunement. Uses the 2024 Flail rules with +1 to attack and damage rolls. Once per Long Rest, when you hit a creature with it, deal an extra 1d6 Thunder damage. Each creature within 60 feet can hear the crack under ordinary conditions. No chain Grapple, reach increase or extra attack is granted.', 'Original Thunder God Kusarigama-inspired draft; no elemental stacking, stance tree or automatic status buildup.', 'A loud strike can serve as a signal, but also alerts nearby enemies.', 'Small metal rings tremble before the chain is swung.',True,'rare',True,'open5e-srd-2024:srd-2024_flail')
# Mixed OA source: all names are explicitly lesser project versions, not claims of 3e provenance.
for key,name,typ,icon,value,details,tldr,flavor,creative in [
 ('spider-claws','Nekode of the Spider (Lesser)','wondrous-item','gloves',4000,'Requires attunement. Once per Long Rest, as a Magic action, cast Spider Climb on yourself without a spell slot or components. It requires your Concentration and otherwise uses the spell’s normal duration and limits. These gloves do not also grant a weapon attack.','Climb with a daily spell that still needs Concentration.','Fine threads trail from the glove seams, then vanish.','Scout a high window while keeping a route down if Concentration ends.'),
 ('courtiers-obi','Courtier’s Obi (Lesser)','belt','belt',400,'Requires attunement. Once per Long Rest, before making a Charisma (Persuasion) check during a peaceful conversation, add 1d4 to that check. Declare before rolling. It cannot compel agreement or alter a creature’s memories.','A sash grants one small social boost each day.','Its knot settles neatly without a mirror.','Support a well-prepared introduction; hostile demands still face their normal limits.'),
 ('writing-set','Wondrous Writing Set (Lesser)','tools','tools',400,'Requires attunement. The case supplies ink for ordinary writing without refilling. Once per Long Rest, as a Magic action, cast Illusory Script without a spell slot or components. Use the normal casting time of 1 minute in place of the action stated here; all other spell limits apply. It does not forge signatures, counterfeit authority or reveal languages.','An ink case can conceal one written message each day.','The brush leaves a dark line until its last stroke is finished.','Hide instructions in ordinary correspondence; discovery and interception remain possible.'),
 ('twilight-lantern','Twilight Lantern (Lesser)','wondrous-item','lantern',400,'Requires attunement. As a Magic action, light or extinguish this fuel-free lantern. It sheds Dim Light in a 20-foot radius. Once per Long Rest, while lit, you can choose to see invisible creatures and objects within its light for 1 minute. This grants no vision through solid objects and does not reveal Ethereal creatures.','A dim lantern can briefly reveal invisible things nearby.','The wick burns blue without heat.','Sweep a small room for an unseen watcher; the lantern also reveals your position.'),
 ('paper-of-forms','Paper of Forms (Lesser)','consumable','scroll',100,'As a Magic action, consume one sheet to create a plainly magical paper model of a nonliving handheld object no larger than a 1-foot cube, lasting 1 hour. It weighs 1 ounce, cannot function as a weapon, tool, key, food or material component, and unfolds if used to bear more than 1 pound.','Make a temporary paper prop, not a working tool.','Creases arrange themselves around an unfinished outline.','Create a visual marker or a prop for a distraction; touch reveals its paper construction.'),
 ('protection-bell','Bell of Protection (Lesser)','wondrous-item','instrument',400,'Requires attunement. Once per Long Rest, as a Magic action, cast Alarm without components or a spell slot, using its normal casting time of 1 minute instead of that action. Choose an audible alarm. The spell follows all its normal area, triggering and duration limits.','Set a daily audible perimeter alarm.','The bell’s first ring is always quieter than expected.','Watch the entrance while you rest; the alarm cannot identify a visitor.'),
 ('storing-kimono','Kimono of Storing (Lesser)','clothing','clothing',400,'Requires attunement. As a Utilize action, place one nonliving object weighing no more than 1 pound and fitting inside a 6-inch cube into an empty enchanted sleeve pocket. The pocket holds at most one object. Another Utilize action retrieves it. The stored object remains on your person, counts toward carried weight, and can be found by searching the pocket. No extradimensional space or stasis is created.','Keep one small object safely within easy reach.','A single embroidered pocket is deeper than it looks.','Protect a delicate token from accidental loss; a search can still find it.'),
 ('stillness-dust','Dust of Stillness (Lesser)','consumable','dye',100,'As a Magic action, expend one sachet and choose one creature within 10 feet. It makes a DC 12 Strength saving throw. On a failure, its Speed is reduced by 10 feet until the end of its next turn, to a minimum of 0. It is not Restrained or Paralyzed. This affects only movement that uses its Speed, not forced movement or teleportation.','Briefly slow one pursuer with enchanted dust.','Pale grains cling to boots like winter frost.','Gain a small head start; a fast enemy may still catch you.')]:
 custom(key,name,'oa-fan-magic','publication:oriental-adventures-mixed',typ,icon,value,tldr,details,'Independent lesser adaptation from a mixed-edition name lead; original-book edition and full powers unverified. Pricing is a project estimate.',creative,flavor,True,'uncommon',typ!='consumable')
# Clarify casting time in two utility entries without contradictory action clauses.
for r in items:
 if r['id']=='ninja:writing-set':r['details']='Requires attunement. The case supplies ink for ordinary writing without refilling. Once per Long Rest, cast Illusory Script without a spell slot or components, using the spell’s normal casting time of 1 minute and all other normal limits. It does not forge signatures, counterfeit authority or reveal languages.'
 if r['id']=='ninja:protection-bell':r['details']='Requires attunement. Once per Long Rest, cast Alarm without components or a spell slot, using its normal casting time of 1 minute. Choose an audible alarm. The spell follows all its normal area, triggering and duration limits.'
# Preserve reference equipment prices for cosmetic reskins instead of inventing a flat cost.
base_items={r['id']:r for r in map(json.loads,(ROOT/'catalog/items.jsonl').read_text().splitlines())}
for row in items:
 if row['mode']=='2024-equipment-reskin':
  values=base_items[row['base_item_id']]['valuation']['base_values']
  if values:row['estimated_value_gp']=values[0]['amount_gp']
pack={'schema_version':1,'id':'ninja-2024-drafts','label':'Ninja equipment 2024 project drafts','coverage':'Selected 2e handbook name leads, approximate OA equipment mappings, mixed-edition OA lesser magic and game-inspired originals. Not a complete sourcebook conversion or a ninja-class implementation.','sources':refs,'entities':entities,'items':items}
pack['filter_profiles']=[{'id':'ninja-workbench','label':'Ninja equipment workbench','filters':{'tags':['theme:ninja']},'note':'Original drafts plus directly relevant game references. A theme is not a class proficiency or ancestry restriction.'},{'id':'ninja-2024-drafts','label':'Ninja 2024 drafts only','filters':{'sources':['ninja-2024-drafts'],'rulesets':['dnd-2024']},'note':'Original unplaytested drafts. The tabletop-2024 reference profile excludes these drafts.'}]
save(folder/'research-pack.json',pack)
queue={'workstreams':[{'id':k,'label':label,'status':status,'original_book_item_audit_complete':False} for k,label,status in [('complete-ninja-handbook',"The Complete Ninja’s Handbook (2e)",'selected-equipment-reskins-magic-chapter-pending'),('oriental-adventures-3e','Oriental Adventures (2001, 3.0)','selected-equipment-drafts-edition-audit-pending'),('ninja-video-games','Ninja game equipment research','selected-games-indexed-and-original-drafts')]],'next_priority':['verify-2e-miscellaneous-equipment-and-magic-items','verify-2001-OA-item-editions','Tenchu-release-specific-audit','Ninja-Gaiden-release-specific-audit','ninja-tools-from-Ghost-of-Tsushima-and-Final-Fantasy'],'review_policy':'References are not converted items. No cultural ancestry or class proficiency inferred from a theme.'}
for game,label in [('baldurs-gate-1','Baldur’s Gate I / Enhanced Edition'),('baldurs-gate-2','Baldur’s Gate II'),('diablo-1','Diablo I'),('diablo-2','Diablo II'),('diablo-3','Diablo III')]:
 queue['workstreams'].append({'id':game,'label':label,'status':'selected-names-types-reference-imported-tabletop-adaptation-pending','original_book_item_audit_complete':False})
save(folder/'research-queue.json',queue)
print('Ninja drafts',len(items))
